parameters.jsCode:
const items = $input.all();

return items.map(item => {
  try {
    let text =
      item.json.output ||
      item.json.text ||
      item.json.response ||
      '';

    if (!text) {
      return {
        json: {
          text: 'Sorry, I was unable to generate a response. Please try again or contact Bishal directly at bishalranjitofficial@gmail.com.'
        }
      };
    }

    // Strip residual markdown
    text = text
      .replace(/\*\*/g, '')
      .replace(/\*/g, '')
      .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
      .replace(/^#{1,6}\s+/gm, '');

    // Strip any leaked tool call syntax e.g. <function=...></function> or <function=... />
    text = text
      .replace(/<function=[^>]*\/>/gi, '')
      .replace(/<function=[^>]*>.*?<\/function>/gis, '')
      .replace(/```[\s\S]*?```/g, '');

    // Collapse multiple blank lines left behind by stripping
    text = text.replace(/\n{3,}/g, '\n\n');

    return {
      json: {
        text: text.trim()
      }
    };
  } catch (error) {
    return {
      json: {
        text: 'An unexpected error occurred. Please try again or reach out to bishalranjitofficial@gmail.com.'
      }
    };
  }
});
